#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>
#include <cmath>
#include <vector>

namespace off {
constexpr uintptr_t viewMatrix = 0x0;
constexpr uintptr_t entityList = 0x0;
constexpr uintptr_t localPlayer = 0x0;
constexpr uintptr_t entityStride = 0x10;
constexpr int maxEntities = 64;
constexpr uintptr_t health = 0x0;
constexpr uintptr_t team = 0x0;
constexpr uintptr_t dormant = 0x0;
constexpr uintptr_t boneMatrix = 0x0;
constexpr int headBone = 8;
constexpr uintptr_t boneStride = 0x30;
constexpr uintptr_t boneX = 0x0C;
constexpr uintptr_t boneY = 0x1C;
constexpr uintptr_t boneZ = 0x2C;
}

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
struct Matrix { float m[16]; };

class Process {
public:
    DWORD pid = 0;
    HANDLE handle = nullptr;
    uintptr_t base = 0;

    bool attach(const wchar_t* exe, const wchar_t* module) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
            if (!_wcsicmp(pe.szExeFile, exe)) { pid = pe.th32ProcessID; break; }
        CloseHandle(snap);
        if (!pid) return false;

        handle = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!handle) return false;

        snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return false;
        MODULEENTRY32W me{};
        me.dwSize = sizeof(me);
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
            if (!_wcsicmp(me.szModule, module)) { base = reinterpret_cast<uintptr_t>(me.modBaseAddr); break; }
        CloseHandle(snap);
        return base != 0;
    }

    template <class T>
    T read(uintptr_t addr) const {
        T v{};
        ReadProcessMemory(handle, reinterpret_cast<LPCVOID>(addr), &v, sizeof(T), nullptr);
        return v;
    }

    ~Process() { if (handle) CloseHandle(handle); }
};

struct Entity {
    uintptr_t addr;
    int health;
    int team;
    Vec3 head;
};

struct Snapshot {
    Matrix view{};
    uintptr_t local = 0;
    int localTeam = 0;
    std::vector<Entity> enemies;
};

inline bool readSnapshot(const Process& p, Snapshot& s) {
    s.view = p.read<Matrix>(p.base + off::viewMatrix);
    s.local = p.read<uintptr_t>(p.base + off::localPlayer);
    if (!s.local) return false;
    s.localTeam = p.read<int>(s.local + off::team);
    s.enemies.clear();

    const uintptr_t list = p.base + off::entityList;
    for (int i = 0; i < off::maxEntities; ++i) {
        uintptr_t e = p.read<uintptr_t>(list + i * off::entityStride);
        if (!e || e == s.local) continue;
        if (p.read<bool>(e + off::dormant)) continue;
        int hp = p.read<int>(e + off::health);
        int tm = p.read<int>(e + off::team);
        if (hp <= 0 || tm == s.localTeam) continue;
        uintptr_t bones = p.read<uintptr_t>(e + off::boneMatrix);
        if (!bones) continue;
        uintptr_t b = bones + off::headBone * off::boneStride;
        Vec3 head{p.read<float>(b + off::boneX), p.read<float>(b + off::boneY), p.read<float>(b + off::boneZ)};
        s.enemies.push_back({e, hp, tm, head});
    }
    return true;
}

inline bool worldToScreen(const Matrix& vm, const Vec3& w, int sw, int sh, Vec2& out) {
    const float* m = vm.m;
    float cw = m[12] * w.x + m[13] * w.y + m[14] * w.z + m[15];
    if (cw < 0.01f) return false;
    float cx = m[0] * w.x + m[1] * w.y + m[2] * w.z + m[3];
    float cy = m[4] * w.x + m[5] * w.y + m[6] * w.z + m[7];
    out.x = sw * 0.5f + sw * 0.5f * cx / cw;
    out.y = sh * 0.5f - sh * 0.5f * cy / cw;
    return true;
}

#include "mem.h"
#include <algorithm>
#include <chrono>
#include <cstdio>
#include <thread>

using namespace std::chrono;

constexpr const wchar_t* kExe = L"game.exe";
constexpr const wchar_t* kModule = L"client.dll";
constexpr float kFov = 240.f;
constexpr float kDuration = 0.18f;
constexpr float kSens = 1.0f;
constexpr int kAimKey = VK_RBUTTON;
constexpr int kExitKey = VK_END;

static float easeInOutCubic(float t) {
    return t < 0.5f ? 4.f * t * t * t : 1.f - std::pow(-2.f * t + 2.f, 3.f) / 2.f;
}

static void moveMouse(int dx, int dy) {
    INPUT in{};
    in.type = INPUT_MOUSE;
    in.mi.dx = dx;
    in.mi.dy = dy;
    in.mi.dwFlags = MOUSEEVENTF_MOVE;
    SendInput(1, &in, sizeof(in));
}

static bool gameClientRect(const Process& p, RECT& rc) {
    HWND w = GetForegroundWindow();
    DWORD pid = 0;
    GetWindowThreadProcessId(w, &pid);
    if (pid != p.pid) return false;
    return GetClientRect(w, &rc) && rc.right > 0 && rc.bottom > 0;
}

static const Entity* pickTarget(const Snapshot& s, int sw, int sh, Vec2& screen) {
    const Entity* best = nullptr;
    float bestDist = kFov;
    const float cx = sw * 0.5f, cy = sh * 0.5f;
    for (const auto& e : s.enemies) {
        Vec2 p;
        if (!worldToScreen(s.view, e.head, sw, sh, p)) continue;
        float d = std::hypot(p.x - cx, p.y - cy);
        if (d < bestDist) {
            bestDist = d;
            best = &e;
            screen = p;
        }
    }
    return best;
}

int main() {
    Process proc;
    while (!proc.attach(kExe, kModule)) {
        std::puts("waiting for process...");
        std::this_thread::sleep_for(seconds(1));
    }
    std::printf("attached pid=%lu base=0x%llx\n", proc.pid, static_cast<unsigned long long>(proc.base));

    Snapshot snap;
    uintptr_t locked = 0;
    float t = 0.f, rx = 0.f, ry = 0.f;
    auto last = steady_clock::now();

    while (!(GetAsyncKeyState(kExitKey) & 1)) {
        auto now = steady_clock::now();
        float dt = duration<float>(now - last).count();
        last = now;
        std::this_thread::sleep_for(milliseconds(1));

        RECT rc{};
        if (!(GetAsyncKeyState(kAimKey) & 0x8000) || !gameClientRect(proc, rc) || !readSnapshot(proc, snap)) {
            locked = 0;
            continue;
        }

        const int sw = rc.right, sh = rc.bottom;
        Vec2 target{};
        const Entity* e = pickTarget(snap, sw, sh, target);
        if (!e) {
            locked = 0;
            continue;
        }

        if (e->addr != locked) {
            locked = e->addr;
            t = 0.f;
            rx = ry = 0.f;
        }

        float tp = t;
        t = std::min(1.f, t + dt / kDuration);
        float ep = easeInOutCubic(tp), en = easeInOutCubic(t);
        float frac = ep >= 1.f ? 1.f : (en - ep) / (1.f - ep);

        float dx = (target.x - sw * 0.5f) * frac * kSens + rx;
        float dy = (target.y - sh * 0.5f) * frac * kSens + ry;
        int ix = static_cast<int>(dx), iy = static_cast<int>(dy);
        rx = dx - ix;
        ry = dy - iy;
        if (ix || iy) moveMouse(ix, iy);
    }
    return 0;
}
